-- place-pages 06 (BP app): the About and links of 110 places that were in the app before 2026-11-17.
-- Each About was researched from the place's own site and other sources, and each part passed two
-- separate agent checks (one on facts, one on identity); Jesse's yes to that rule for this backfill,
-- 2026-11-17. Links: website first, the place's own pages; wrong ones (Yelp, a Missouri or Michigan
-- namesake, a hijacked or dead domain) taken out. Places whose being open or in town is in doubt got
-- no About: a list for Jesse in BP app docs/plans/place-pages/assets/06-backfill.md.
update public.places set links = '[{"kind": "website", "url": "https://gcremn.com/24-north-lofts/"}, {"kind": "facebook", "url": "https://www.facebook.com/GCREmn"}]'::jsonb, about = '24 North is a loft apartment building at 24 College Avenue North in downtown St. Joseph, managed by GC Real Estate Partners of St. Cloud. It has one- and two-bedroom single-level lofts with in-unit laundry, stainless steel appliances, fireplaces, walk-in closets and oversized balconies. Residents share a fitness and yoga room, garage parking, bike storage and a rooftop deck, and pets are welcome.' where entry_id = '24-north-lofts-on-college-avenue';
update public.places set links = '[{"kind": "website", "url": "http://www.2ndavecuts.com/"}]'::jsonb, about = '2nd Avenue Cuts is a hair salon and cut shop at 17 2nd Avenue NW in St. Joseph, run by stylist Serina, who has more than 18 years of experience. It offers haircuts, styling, beard and moustache trims and shampoos for adults and kids, with an old-school barbershop feel and classic, vintage and modern looks. College students with a valid ID get a special rate, and clients are seen by appointment only.' where entry_id = '2nd-avenue-cuts';
update public.places set links = '[{"kind": "website", "url": "https://centennial.legion.org/minnesota/post328"}]'::jsonb where entry_id = '328-american-legion-post';
update public.places set links = '[{"kind": "website", "url": "https://www.tccmaterials.com/location/st-joseph-mn/"}, {"kind": "facebook", "url": "https://www.facebook.com/TCCMaterialsMasonry"}, {"kind": "instagram", "url": "https://www.instagram.com/tcc_materials_masonry"}]'::jsonb, about = 'Amcon Block & Precast is the St. Joseph location of TCC Materials, a Minnesota company based in Mendota Heights that began in 1927 as Twin City Concrete Products Company. Amcon is one of the company''s brand names. MnDOT lists TCC Materials in St. Joseph as a qualified maker of precast equipment pads and light foundations. TCC Materials also produces masonry block, packaged concrete, mortars, grouts and hardscape products.' where entry_id = 'amcon-block-precast';
update public.places set links = '[{"kind": "website", "url": "https://www.american-manufacturing.com/"}]'::jsonb, about = 'American Mfg Co makes drilling mud pumps and replacement parts at its plant on 19th Avenue NE in St. Joseph, with a second factory in Houston, Texas. It started out making spare parts for the water-well drilling industry and now also serves geothermal, mineral exploration and oil and gas drilling. The shop runs about 30 CNC machines and its own heat-treating, and holds API 7-K, API Q-1 and ISO 9001:2015 certifications.' where entry_id = 'american-manufacturing-group';
update public.places set links = '[{"kind": "website", "url": "https://www.angelstouchmassagemn.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/AngelsTouchMassageMN"}]'::jsonb, about = 'Angel''s Touch Massage is the St. Joseph practice of Rose Janssen, a certified massage therapist who started the business from her home in 2002 and moved it into an office in 2007. She trained at Sister Rosalind School of Massage and later taught there for six years. Sessions follow how the body responds rather than a set routine, and since 2026 she also teaches Fascial Maneuvers in classes and one-on-one coaching.' where entry_id = 'angels-touch-massage';
update public.places set links = '[{"kind": "website", "url": "https://linktr.ee/annereneebridalco"}, {"kind": "facebook", "url": "https://www.facebook.com/profile.php?id=61579677901590"}, {"kind": "instagram", "url": "https://www.instagram.com/annereneebridalcompany"}]'::jsonb, about = 'Anne Renee Bridal Co. is a bridal shop at 33 1st Avenue NW in St. Joseph. It carries wedding gowns in sizes 2 to 24, along with mother-of-the-bride dresses, tuxedos and prom wear. Its designers include Stella York by Essense Designs and Morilee New York, and appointments can be requested online through the shop''s booking page.' where entry_id = 'anne-renee-bridal';
update public.places set links = '[{"kind": "website", "url": "https://www.csbsju.edu/fine-arts/visual-arts/"}]'::jsonb where entry_id = 'arts-benedicta-center';
update public.places set links = '[{"kind": "website", "url": "https://www.stearnselectric.org/"}, {"kind": "facebook", "url": "https://www.facebook.com/stearnselectric"}, {"kind": "instagram", "url": "https://www.instagram.com/stearnselectricmn"}]'::jsonb, about = 'Stearns Electric Association is a member-owned electric distribution cooperative, founded by local farmers in 1937 with help from the Rural Electrification Administration. It serves more than 28,000 members across six Central Minnesota counties: Stearns, Todd, Morrison, Kandiyohi, Pope and Douglas. Its headquarters is in Melrose, and its St. Joseph office is open by appointment.' where entry_id = 'association-electric-stearns';
update public.places set links = '[{"kind": "website", "url": "https://hulstrucking.com/"}]'::jsonb, about = 'Avon Ag-Lime is the agricultural lime business of Huls Bros Trucking, run from its yard at 13266 Collegeville Road near St. Joseph. The Minnesota Department of Agriculture lists it as a contract land spreader with four lime spreaders, working anywhere in the state and also offering hauling. Huls Bros has been trucking for more than 30 years and does custom spreading of lime and animal waste.' where entry_id = 'avon-ag-lime';
update public.places set links = '[{"kind": "website", "url": "https://www.bdhservice.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/BDHserviceinc"}]'::jsonb, about = 'BDH Service & Performance is a heavy equipment repair company that serves all of Minnesota. It repairs forklifts, skid loaders, telehandlers, sweepers and other construction equipment on site or in its shop, and also works on fleet vehicles, cars and trailers. It describes itself as an independent shop that brings mobile service to the job site.' where entry_id = 'bdh-service-performance';
update public.places set links = '[{"kind": "website", "url": "https://www.blissdirect.com/"}]'::jsonb, about = 'Bliss Direct Media is a direct mail company on 15th Avenue NE in St. Joseph. In 2017 it launched what it calls the first complete online direct mail management system, and clients now design, personalize, proof and send mail from one platform, including AppealMaker for nonprofits. Every order is printed and mailed from its own production facility.' where entry_id = 'bliss-direct-media';
update public.places set links = '[{"kind": "website", "url": "https://www.clexcavating.com/"}]'::jsonb, about = 'C&L Excavating is a family-owned excavating company in St. Joseph, started in 1997 by Brent Lahr and Kevin Cox, who together bring more than 40 years of experience. It works for homeowners, businesses and cities on sewer and water lines, septic systems, water mains, storm and sanitary sewers, and road and street reconstruction. It also sells and delivers black dirt, gravel, rock, bituminous millings and aggregate.' where entry_id = 'c-l-excavating';
update public.places set links = '[{"kind": "website", "url": "https://www.capitalstoragerental.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/capitalstorage"}]'::jsonb, about = 'Capital Storage Rental is a self-storage facility on Ridgewood Court in St. Joseph, just off County Road 75 behind Beeline Marine. It offers indoor units from 5x10 to 10x30 and large outdoor spaces for campers, boats, trailers, fish houses and RVs. Renters can book online and move in right away, with 24-hour drive-up access and online bill pay.' where entry_id = 'capital-storage-rental-of-st-joseph';
update public.places set links = '[{"kind": "website", "url": "https://www.stjosephmn.gov/Facilities/Facility/Details/1"}]'::jsonb, about = 'Centennial Park is a 2.3-acre city park at the northwest edge of downtown St. Joseph, within walking distance of downtown shops and restaurants. It has a playground, a full-size basketball court, picnic tables, benches, a drinking fountain and updated ADA restrooms. Its lighted community pavilion can be rented from the City of St. Joseph for gatherings from May through September.' where entry_id = 'centennial-park';
update public.places set links = '[{"kind": "facebook", "url": "https://www.facebook.com/319461131813391"}]'::jsonb, about = 'Central Canvas Manufacturing, a St. Joseph canvas maker, has been in business for more than 30 years, mostly as an OEM maker for the marine and fish house industries, along with private label bags and contract sewing. Its products include boat covers, boat lift canopies, pontoon covers and bimini tops. In 2015 it started Rustic River Gear, a line of handmade waxed canvas and leather bags with a lifetime guarantee.' where entry_id = 'central-canvas-manufacturing';
update public.places set links = '[{"kind": "website", "url": "https://www.centralminnesotadetailing.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/profile.php?id=61580024969402"}, {"kind": "instagram", "url": "https://www.instagram.com/centralminnesotadetailing"}]'::jsonb, about = 'Central Minnesota Detailing is a car detailing shop in St. Joseph that cleans the interior and exterior of all types of vehicles, at its shop or through mobile service. Exterior detailing restores shine and protection, interior detailing includes vacuuming, steam cleaning and leather conditioning, and a full package combines both. The crew uses high-quality products for a thorough clean.' where entry_id = 'central-minnesota-detailing';
update public.places set links = '[{"kind": "website", "url": "https://rlcmn.church/st-joseph"}, {"kind": "facebook", "url": "https://www.facebook.com/rlcmnstj"}, {"kind": "instagram", "url": "https://www.instagram.com/stjoechurch/"}]'::jsonb, about = 'River of Life Church is one church meeting in several Minnesota towns, and its St. Joseph congregation gathers on Sundays at Kennedy Community School. Its services aim to be upbeat while also spiritually deep, rooted in the belief that the best life comes from being connected with Jesus and following his ways. Pastor Tyler has served there since July 2023.' where entry_id = 'church-life-of-river';
update public.places set links = '[]'::jsonb, about = 'The City of St. Joseph Dog Park is the town''s first dog park, opened by the city in September 2017 on part of Millstream Park. Residents raised part of the cost through donations and the city paid the rest. The fenced first phase is a large open area with trees and a covered picnic table, designed for big dogs, though small dogs are welcome too.' where entry_id = 'city-of-st-joseph-dog-park';
update public.places set links = '[{"kind": "website", "url": "https://www.csbsju.edu/libraries/"}, {"kind": "instagram", "url": "https://www.instagram.com/csbsjulibraries"}]'::jsonb, about = 'Clemens Library is the College of Saint Benedict''s library on its St. Joseph campus, one of the two CSB+SJU libraries alongside Alcuin Library at Saint John''s. It offers collections, research help and learning spaces for the combined student body. Its information desk also lends tech and tools from the libraries'' collection, such as podcasting kits, a digital piano, crafting tools and umbrellas.' where entry_id = 'clemens-library';
update public.places set links = '[{"kind": "website", "url": "https://www.colepapers.com/"}]'::jsonb, about = 'Cole Papers'' St. Cloud-area branch is at 30701 Pearl Drive in St. Joseph, one of the company''s 11 stocking locations across the Upper Midwest. Founded by Robert Cole in 1918 as the Fargo Paper Company, Cole is a wholesale distributor of janitorial and sanitation supplies, packaging, food service supplies and printing papers. Factory-trained technicians also service cleaning equipment.' where entry_id = 'cole-papers';
update public.places set links = '[{"kind": "facebook", "url": "https://www.facebook.com/470484229953813"}]'::jsonb where entry_id = 'collegeville-brokerage';
update public.places set links = '[{"kind": "website", "url": "https://computerrepairunlimited.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/ComputerRepairUnlimited"}]'::jsonb, about = 'Computer Repair Unlimited is a computer repair and IT company on West Birch Street in St. Joseph, established in 2010. Its five full-time staff handle on-demand repair of Windows desktops, laptops and tablets, plus managed IT contracts, sales and consulting for businesses. It specializes in Microsoft server technology, network security and data recovery, and has taken part in forensic investigations of network breaches.' where entry_id = 'computer-repair-unlimited';
update public.places set links = '[{"kind": "website", "url": "https://www.creationsincandles.com/"}]'::jsonb, about = 'Creations In Candles, in St. Joseph, preserves flowers from life''s big moments, such as the loss of a loved one or a celebration of life or love, inside custom-made scented candles. Every candle is hand designed, whether an order is for one candle or fifty. Besides flowers, the candles can hold other keepsakes such as fishing lures, feathers, ribbons, jewelry and pictures.' where entry_id = 'creations-in-candles';
update public.places set links = '[{"kind": "website", "url": "https://www.curtisgroup.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/CurtisGroup"}]'::jsonb, about = 'Curtis Group is a St. Joseph marketing agency that specializes in marketing for dental practices. Its small, dedicated team handles a practice''s whole online presence, from websites and logos to SEO, social media management and online reputation. It treats these as one connected plan, with one team making every part work together rather than a set of separate vendors.' where entry_id = 'curtis-marketing-group';
update public.places set links = '[]'::jsonb where entry_id = 'dancing-bears-b-b';
update public.places set links = '[{"kind": "website", "url": "https://www.stjosephmn.gov/114/Police-Department"}]'::jsonb, about = 'The St. Joseph Police Department gives the city''s more than 7,000 residents 24-hour protection, every day of the year. Chief Dwight Pfannenstein leads a staff of 14, including a deputy chief, two sergeants and eight patrol officers. The department works by community policing, building ties with residents, businesses, schools and groups, and also handles animal control and licensing and a medication drop-off.' where entry_id = 'department-joseph-police-st';
update public.places set links = '[{"kind": "website", "url": "https://djsflowerbar.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/people/DJs-Flower-Bar-Tea/61587345414908/"}]'::jsonb, about = 'DJ''s Flower Bar & Tea is a flower and tea shop on East Birch Street in downtown St. Joseph. At its flower bar, visitors can build their own arrangement or choose a ready-made vased or basket arrangement, roses, a plant or a gift basket. The shop also carries tea, candles, wind chimes, essential oils, chocolates, antiques and decor, and it delivers flowers.' where entry_id = 'djs-flower-bar-tea';
update public.places set links = '[{"kind": "website", "url": "https://www.dktdiesel.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/people/DKT-Auto-Diesel-Repair-LLC/61575100463483/"}]'::jsonb, about = 'DKT Auto & Diesel Repair is a repair shop in St. Joseph for gas and diesel vehicles, working on both repairs and modifications. It opened in April 2025 with the aim of being a judgment-free shop. The mechanics make a point of showing each customer exactly what is wrong with the vehicle and where the money for the repair goes.' where entry_id = 'dkt-auto-diesel-repair';
update public.places set links = '[{"kind": "website", "url": "https://dovetaildesignremodel.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/DovetailDesignRemodel"}, {"kind": "instagram", "url": "https://www.instagram.com/dovetaildesignremodel"}]'::jsonb, about = 'Dovetail Design & Remodeling designs and remodels kitchens, bathrooms and interior spaces such as primary suites and mudrooms across Central Minnesota. Founder Chris Hensel started the company in 2011, bringing more than 20 years of design and construction experience. Each project starts with a personalized design and carries through the full remodel, a process the company calls the Dovetail Advantage.' where entry_id = 'dovetail-design-remodeling';
update public.places set links = '[{"kind": "website", "url": "https://www.edwardjones.com/us-en/financial-advisor/beau-hanowski"}, {"kind": "facebook", "url": "https://www.facebook.com/Edward-Jones-Financial-Advisor-Beau-Hanowski-720240231455289/"}]'::jsonb, about = 'This Edward Jones branch office sits on West Birch Street in downtown St. Joseph. Financial advisor Beau Hanowski, a Certified Financial Planner, leads the office, and Rhonda Krueger serves as its senior branch office administrator. The office offers investment and financial planning help to local individuals and families as part of the national Edward Jones firm.' where entry_id = 'edward-jones';
update public.places set links = '[{"kind": "facebook", "url": "https://www.facebook.com/people/Elite-Refrigeration-Heating-and-Air-Conditioning/100057452979096/"}]'::jsonb, about = 'Elite Refrigeration, Heating and Air Conditioning is a heating, ventilating and air conditioning service company based in St. Joseph. It sells, services and installs heating and cooling equipment and also takes on refrigeration work. Its customers range from homes to commercial businesses and industrial sites.' where entry_id = 'elite-refrigeration-heating-air-conditio';
update public.places set links = '[{"kind": "website", "url": "https://www.myemeraldlawn.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/emeraldcompanies"}, {"kind": "instagram", "url": "https://www.instagram.com/emeraldcompanies"}]'::jsonb, about = 'Emerald Companies is a locally owned snow and lawn company that Joel Wollum started with a push mower in 1998, and he still oversees its work. It plows and salts commercial lots, makes and spreads liquid salt brine ahead of storms, and runs residential weed-and-feed lawn programs around the St. Cloud area, St. Joseph included. It calls itself Central Minnesota''s largest salt brine producer.' where entry_id = 'emerald-companies';
update public.places set links = '[{"kind": "website", "url": "https://www.executiveexpress.biz/"}, {"kind": "facebook", "url": "https://www.facebook.com/ExecutiveExpressShuttle"}]'::jsonb, about = 'Executive Express is a private transportation company based on Elm Street East in St. Joseph, in the business since 1979. It runs airport transfers to Minneapolis-St. Paul, St. Cloud and Brainerd, black car service, hourly charters for groups of 2 to more than 200, employee shuttles and same-day courier delivery. It also has a branch at Brainerd Lakes Regional Airport.' where entry_id = 'executive-express';
update public.places set links = '[{"kind": "facebook", "url": "https://www.facebook.com/Teresajohnsonst.joseph/"}]'::jsonb where entry_id = 'fieldstone-farm';
update public.places set links = '[{"kind": "website", "url": "https://finelineentertainment.net/"}, {"kind": "facebook", "url": "https://www.facebook.com/FineLineDj/"}]'::jsonb where entry_id = 'fine-line-entertainment';
update public.places set links = '[{"kind": "website", "url": "https://geriscountrykennelsmn.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/GerisCountryKennels"}]'::jsonb, about = 'Geri''s Country Kennels is a dog-only boarding and daycare kennel in the countryside near St. Joseph, founded by Geri in 1999. Dogs stay in heated and air-conditioned indoor kennels, play in three covered play areas and walk on country trails away from traffic. It offers overnight boarding and supervised daycare, and does not board cats, birds or other animals.' where entry_id = 'geris-country-kennels';
update public.places set links = '[{"kind": "facebook", "url": "https://www.facebook.com/goldcountrytrucking"}]'::jsonb, about = 'Gold Country Trucking is a regional trucking company on Sterling Drive in St. Joseph that mainly runs freight across the Upper Midwest. It pulls vans and refrigerated trailers with its own company trucks, new Peterbilt glider trucks and owner-operators. Federal carrier records list 17 power units hauling general freight, refrigerated food and beverages for hire.' where entry_id = 'gold-country-trucking';
update public.places set links = '[{"kind": "website", "url": "http://www.granitecitymotorcar.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/granitecitymotorcar"}, {"kind": "instagram", "url": "https://www.instagram.com/granitecitymotorcar"}]'::jsonb, about = 'Granite City Motor Car is a vehicle dealership on County Road 75 in St. Joseph, with a second lot in Ramsey. It sells new and used cars, trucks, crossovers, SUVs, vans and fleet vehicles, and offers financing, trade-in values and service. The dealership describes itself as a personal concierge for buyers and puts its focus on long-term customer relationships.' where entry_id = 'granite-city-motor-car';
update public.places set links = '[{"kind": "website", "url": "https://granitecitywindow.com/"}]'::jsonb, about = 'Granite City Window Cleaning is a locally owned company based on Polar Circle in St. Joseph that has cleaned windows across central Minnesota for more than 28 years. Its crew handles window cleaning, gutter cleaning and power washing in St. Joseph, St. Cloud, Sauk Rapids, Sartell, Waite Park and nearby towns.' where entry_id = 'granite-city-window-cleaning';
update public.places set links = '[{"kind": "website", "url": "http://heirbornkennels.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/HeirbornFCR"}]'::jsonb, about = 'Heirborn Kennels in St. Joseph is dedicated to the health and advancement of the Flat-Coated Retriever. Its work with dogs began in the early 1970s with show ring, obedience and bird hunting; it got its first Flat-Coat in 1978 and bred its first litter in 1996. It has bred nearly 50 breed champions, and its dogs serve as family pets, hunting companions, therapy dogs, show dogs and nationally certified search and rescue dogs.' where entry_id = 'heirborn-kennels';
update public.places set links = '[]'::jsonb, about = 'Heymans Design is the furniture business of Steven Heymans in St. Joseph. He designs and makes furniture he would want in his own home, most of it from wood bought from sawyers within a 45-minute drive, mostly red oak, white oak, walnut and cherry, and most pieces have a clear finish. Prairie-style and Bauhaus architecture shape his work, which includes a red oak lounge chair and ottoman, a rocking chair and a parabola-shaped oak table. He has been a Maker Marketplace member since 2014.' where entry_id = 'heymans-design';
update public.places set links = '[{"kind": "website", "url": "https://www.holisticflowerfarm.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/profile.php?id=61557378525198"}, {"kind": "instagram", "url": "https://www.instagram.com/holistic_flower_farm"}]'::jsonb, about = 'Holistic Flower Farm is a small flower farm near St. Joseph where Amy, a former obstetrics nurse, holistic health nurse and Master Gardener, grows seasonal flowers and herbs. She makes bouquets and arrangements for weddings, prom, holidays, sympathy and other occasions, along with handmade items inspired by the garden. Her fresh bouquets also appear at the farmers market at the St. Cloud VA Medical Center.' where entry_id = 'holistic-flower-farm';
update public.places set links = '[]'::jsonb where entry_id = 'impressions-hair-studio';
update public.places set links = '[{"kind": "website", "url": "https://bearingsystems.istate.com/locations/?id=176"}, {"kind": "facebook", "url": "https://www.facebook.com/102512295061598"}]'::jsonb, about = 'Interstate Bearing Systems in St. Joseph is the central Minnesota branch of an industrial parts distributor that belongs to Interstate Companies. The branch supplies bearings, seals, power transmission parts, electric motors, gearboxes and conveyor components to agriculture, aggregate, food and beverage and manufacturing customers. It also offers conveyor and gearbox repair, electric motor rewinds, condition monitoring and inventory support.' where entry_id = 'interstate-bearing-systems';
update public.places set links = '[{"kind": "facebook", "url": "https://www.facebook.com/p/JG-Auto-Detail-61566517191943"}]'::jsonb where entry_id = 'j-g-auto-detail';
update public.places set links = '[]'::jsonb, about = 'Jet-Black of St. Cloud is the St. Cloud-area location of Jet-Black, an asphalt maintenance company that has sealed driveways since 1987 and has locally owned locations in 21 states. Its crews do sealcoating, crack filling, patchwork and other asphalt repair for homeowners, property managers and contractors.' where entry_id = 'jet-black';
update public.places set links = '[{"kind": "website", "url": "https://info2851788.wixsite.com/jkmonumentsmn"}]'::jsonb, about = 'JK Monuments is a family-owned monument business on 83rd Avenue near St. Joseph that serves families across central Minnesota. Its owners bring a combined 30-plus years of ownership in the trade, and visits are by appointment. The business works by its motto that when someone you love becomes a memory, the memory becomes a treasure.' where entry_id = 'jk-monuments';
update public.places set links = '[{"kind": "website", "url": "https://www.saintjosephjoes.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/stjosephjoes/"}]'::jsonb, about = 'The St. Joseph Joes are the town''s amateur baseball team, playing in the Sauk Valley League with home games at Schneider Field in Memorial Park. Managed by Pat Schneider of St. Joseph, the Joes finished second in the Sauk Valley West in 2024 and went on to the State Amateur Baseball Tournament for the first time since 2017.' where entry_id = 'joes-joseph-st';
update public.places set links = '[{"kind": "website", "url": "https://locations.tacojohns.com/mn/saint-joseph/211-county-rd-75-w/"}, {"kind": "facebook", "url": "https://www.facebook.com/tacojohns"}, {"kind": "instagram", "url": "https://www.instagram.com/tacojohns"}]'::jsonb, about = 'This Taco John''s on County Road 75 West in St. Joseph serves the chain''s tacos, burritos and Potato Olés. Taco John''s began as a small taco stand in Cheyenne, Wyoming, in 1969 and now runs and franchises more than 300 restaurants in 21 states. Its menu is known for Crispy Tacos, Meat and Potato Burritos and handmade salsas, and the chain says it started Taco Tuesday.' where entry_id = 'johns-taco';
update public.places set links = '[{"kind": "website", "url": "https://tools.usps.com/locations/details/1380378"}]'::jsonb where entry_id = 'joseph-office-post-st';
update public.places set links = '[{"kind": "website", "url": "https://youniquewellnessllc.massagetherapy.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/JustinaMassage"}]'::jsonb, about = 'Justina Massage is the St. Joseph studio of Justina, owner and certified massage therapist at YOUnique Wellness on West Minnesota Street. She completed the 800-hour program at Sister Rosalind''s School of Massage in Sauk Rapids, then joined its staff, and opened her own studio in St. Joseph in 2011. She offers therapeutic massage fitted to each client, including Swedish, deep tissue, trigger point, myofascial release, reflexology and prenatal massage.' where entry_id = 'justina-massage';
update public.places set links = '[]'::jsonb where entry_id = 'k-autobody';
update public.places set links = '[]'::jsonb where entry_id = 'keltic-konstruction';
update public.places set links = '[{"kind": "website", "url": "https://www.tccmaterials.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/people/King-of-Hearths/100054348708323/"}]'::jsonb where entry_id = 'king-of-hearths';
update public.places set links = '[{"kind": "website", "url": "http://www.kingskennelsmn.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/kingskennelsmn"}]'::jsonb, about = 'King''s Kennels is located near Saint John''s University in beautiful central Minnesota. Established in 1994, owner Paula King started with the idea of running a business out of her home that could involve Paula''s passion for dogs while utilizing the land in its rural setting. Naturally, the perfect fit was the idea of a facility for boarding dogs.' where entry_id = 'kings-kennels';
update public.places set links = '[{"kind": "website", "url": "http://www.kleinbuildersmn.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/kleinbuilders"}]'::jsonb, about = 'Klein Builders has built homes in the St. Joseph area since 1983, first as Klein-Goerger Builders. Owners Mark, Jason and Randy Klein and Matt Loso work on every home they build, and Sherrie Klein runs the office. The company builds custom homes on its lots or the buyer''s, and does remodels, concrete flatwork, stamped and colored concrete and stonework from Avon and Albany to Cold Spring and St. Cloud.' where entry_id = 'klein-builders';
update public.places set links = '[{"kind": "website", "url": "https://www.stjosephmn.gov/Facilities/Facility/Details/Klinefelter-Park-4"}]'::jsonb, about = 'Klinefelter Park is a city park in a residential neighborhood on Dale Street East. A paved walking trail loops around a central wetland and through a mature oak stand on the east side, crossing two pedestrian bridges, with benches that look out over the wetland. The park is kept in a natural state where wildlife lives alongside visitors, and it has a playground, a picnic shelter, bathrooms and parking.' where entry_id = 'klinefelter-park';
update public.places set links = '[{"kind": "facebook", "url": "https://www.facebook.com/KostrebaApplianceServiceCenter"}]'::jsonb where entry_id = 'kostreba-appliance-services-center';
update public.places set links = '[{"kind": "website", "url": "https://www.stearnscountymn.gov/kraemer-lake-wildwood-county-park"}]'::jsonb, about = 'Kraemer Lake-Wildwood County Park is a 265-acre Stearns County park with half a mile of lake frontage, about 2 miles west of St. Joseph on County Road 51. Half the site is a significant remnant natural community with trees 300 years old. Natural-surface trails serve walkers, bikers and leashed dogs, and in winter there are groomed cross-country ski trails and packed trails for snowshoes and fat-tire bikes. Wildwood Ranch Maple Syrup is made in the park each spring.' where entry_id = 'kraemer-lake-wildwood-county-park';
update public.places set links = '[{"kind": "website", "url": "https://www.kwiktrip.com/locator/store?id=147"}, {"kind": "facebook", "url": "https://www.facebook.com/KWIKTRIP147"}]'::jsonb, about = 'Kwik Trip #147 is a gas station and convenience store on 2nd Avenue NW, one of two Kwik Trip stores in St. Joseph. It sells unleaded, premium and winter diesel fuel, beer, and has a car wash, an ATM and a family restroom. Kwik Trip is a family-owned company rooted in La Crosse, Wisconsin, since 1965, and runs its own bakery, dairy and kitchens for more than 900 stores.' where entry_id = 'kwik-trip';
update public.places set links = '[]'::jsonb, about = 'Leaps and Bounds Childcare is a licensed home daycare in St. Joseph for infants, toddlers and preschoolers. The provider plans learning around the 1-2-3 Curriculum and adds hands-on activities drawn from Montessori and Waldorf education, with a focus on nature and outdoor play.' where entry_id = 'leaps-bounds-childcare-preschool';
update public.places set links = '[]'::jsonb where entry_id = 'lillian-leonard-primary';
update public.places set links = '[{"kind": "facebook", "url": "https://www.facebook.com/littleshopwelding"}]'::jsonb, about = 'Little Shop Welding, LLC is a welding and fabrication shop on County Road 2 that has been in business since 1994. It does custom fabrication and manufacturing and repairs all kinds of metal. The shop works with all steels, stainless steel, aluminum, cast steel and some cast irons, and does MIG, TIG and stick welding.' where entry_id = 'little-shop-welding-repair';
update public.places set links = '[{"kind": "website", "url": "https://lookingoodwindowtint.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/Lookin-Good-Tint-LLC-472251269491530"}]'::jsonb, about = 'Lookin Good Tint has tinted car windows, homes and commercial buildings since 1999 and has built its name across Central Minnesota. Owner Keven runs the shop on 19th Avenue NE, which also puts in decorative and security film, 3M Di-Noc architectural finishes and vinyl graphics. It is an authorized 3M and Llumar dealer.' where entry_id = 'lookin-good-tint';
update public.places set links = '[{"kind": "website", "url": "https://mainstayinsure.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/221564061675556"}]'::jsonb, about = 'Mainstay is an insurance brokerage on Cedar Street East in St. Joseph. As a broker rather than an insurance company, it works for its clients instead of the insurers, comparing options from several insurance companies. It arranges auto, home, commercial, life and health coverage, and its stated mission is to make clients'' lives simpler, safer and better.' where entry_id = 'mainstay';
update public.places set links = '[{"kind": "facebook", "url": "https://www.facebook.com/p/Marks-Wallcoating-100063957636789"}]'::jsonb where entry_id = 'marks-wallcoating';
update public.places set links = '[{"kind": "website", "url": "https://www.mcdonalds.com/us/en-us/location/mn/st-joseph/1180-e-elm-street/35317.html"}, {"kind": "facebook", "url": "https://www.facebook.com/850034138365834"}]'::jsonb, about = 'McDonald''s on Elm Street East is St. Joseph''s location of the fast-food chain; the nearest other McDonald''s restaurants are in Waite Park. It has a dining room with Wi-Fi and self-order kiosks, and a drive-thru that also serves coffee. The kiosks have audio navigation for guests who need help reading the screen.' where entry_id = 'mcdonalds';
update public.places set links = '[{"kind": "website", "url": "https://www.stjosephmn.gov/Facilities/Facility/Details/5"}]'::jsonb, about = 'Memorial Park sits between downtown St. Joseph and a residential neighbourhood on 3rd Avenue NW and is the home of the St. Joseph Saints. It has a baseball field with dugouts, a concession stand, restrooms and parking. A lighted court serves as a skateboard area and becomes a hockey and ice-skating rink in winter, and the park also has a sledding hill.' where entry_id = 'memorial-park';
update public.places set links = '[{"kind": "website", "url": "https://meyerfarmproject.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/642750819093155"}]'::jsonb, about = 'The Meyer Farm Project is an art studio and gathering place on the Meyer family farm south of St. Joseph. Artist and educator Anne Meyer, who was raised on the farm, spent more than a decade renovating its barn into a creative space to share with others. The project asks what one could learn by apprenticing oneself to a place, and builds ties to the land and its non-human life through sustainable craft, food, song and art.' where entry_id = 'meyer-farm-project';
update public.places set links = '[{"kind": "facebook", "url": "https://www.facebook.com/210331519141195"}]'::jsonb, about = 'The Cottages at Mill Stream Village is a 55-plus community of patio homes in the heart of St. Joseph. Each home has its own covered front porch entrance, with a shared main entrance, a resident great room, garages and walking paths around the building. Homes have in-floor heat, large kitchens and main-floor living, a walk from local shops, restaurants, bike paths and the college library.' where entry_id = 'mill-stream-village';
update public.places set links = '[{"kind": "facebook", "url": "https://www.facebook.com/817213361472675"}]'::jsonb where entry_id = 'millan-brothers-construction';
update public.places set links = '[{"kind": "website", "url": "https://www.mafmic.org/"}, {"kind": "facebook", "url": "https://www.facebook.com/Minnesota-Association-of-Farm-Mutual-Insurance-Companies-111386108231908/"}]'::jsonb where entry_id = 'minnesota-association-of-farm-mutual-ins';
update public.places set links = '[{"kind": "website", "url": "https://www.mnhomeimprovements.com/"}]'::jsonb, about = 'Minnesota Home Improvements is a licensed remodeling contractor that has served central Minnesota homeowners since 1975, with an office on Ridgewood Court in St. Joseph and offices in or near St. Cloud, Brainerd and Willmar. Its crews install and repair shingle and metal roofs, gutters, and wood and vinyl windows, and remodel kitchens, bathrooms, decks, porches and siding. The company handles permits and offers financing and warranties on its work.' where entry_id = 'minnesota-home-improvements';
update public.places set links = '[{"kind": "website", "url": "https://www.stjosephmn.gov/Facilities/Facility/Details/7"}]'::jsonb, about = 'Monument Park is a small city park of under half an acre on Birch Street West in St. Joseph, with benches and parking. It holds a historical marker built in the early 1940s that remembers a blockhouse settlers put up for refuge during the Dakota Conflict of 1862. Three pentagonal blockhouses were built in various places from green timber from Joseph Linneman''s flour mill, with walls a foot thick and sides 50 feet long.' where entry_id = 'monument-park';
update public.places set links = '[{"kind": "website", "url": "https://www.mortgagesonmain.com/"}]'::jsonb where entry_id = 'mortgages-on-main';
update public.places set links = '[{"kind": "website", "url": "https://www.namisolutions.com/"}]'::jsonb, about = 'NAMI Solutions, Inc. builds custom responsive websites and handles website maintenance, programming and web hosting for businesses. The company was formed in 2001 to give companies, large and small, one dependable and responsive resource for their changing web and hosting needs. It offers round-the-clock support from staff who explain technical problems in plain language.' where entry_id = 'nami-solutions';
update public.places set links = '[{"kind": "website", "url": "https://truckaccessoriesdirect.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/people/Truck-Accessories-Direct/100089818405338/"}, {"kind": "instagram", "url": "https://www.instagram.com/truckaccessoriesdirect/"}]'::jsonb, about = 'North Central Distributing sells aftermarket parts and accessories for pickup trucks and SUVs from St. Joseph, mostly through its online store, Truck Accessories Direct. The range covers bumpers, grille guards, tonneau covers and running boards, floor mats and seat covers, lighting, lift and leveling kits, and towing hitches. The staff use the products they sell and carry the major brand names.' where entry_id = 'north-central-distributing';
update public.places set links = '[{"kind": "website", "url": "https://thenorthtable.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/profile.php?id=61582164415845"}, {"kind": "instagram", "url": "https://www.instagram.com/thenorthtables"}]'::jsonb, about = 'The North Table is a small scratch kitchen inside Milk & Honey Ciders on County Road 51 in St. Joseph Township. It cooks with flora and fauna from the Great Lakes region, with a menu split into plant-forward dishes, meat and breakfast plates, and house-made desserts, and it works to keep gluten and dairy out of its cooking. Orders can be picked up, and the kitchen also caters weddings and events.' where entry_id = 'north-table';
update public.places set links = '[{"kind": "website", "url": "https://www.stjosephmn.gov/Facilities/Facility/Details/9"}]'::jsonb, about = 'Northland Park is a 9.25-acre city of St. Joseph neighborhood park north of County Road 75, set amid a large housing development. The city describes it as a neighborhood park with plenty of room and activity, and its features include a foot golf course.' where entry_id = 'northland-park';
update public.places set links = '[{"kind": "facebook", "url": "https://www.facebook.com/people/Paquin-SeasonalSelf-Storage/100063503594410/"}]'::jsonb where entry_id = 'paquin-seasonal-self-storage';
update public.places set links = '[{"kind": "website", "url": "https://paulkollmann.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/PaulKollmannMonuments"}]'::jsonb, about = 'Paul Kollmann Monuments is a second-generation, family-owned monument company run by Paul Kollmann in St. Joseph. It sells traditional, modern and custom monuments, markers, benches, vases and personal columbariums, with custom, diamond and laser etching. It also handles cemetery lettering and delivery, and many of its customers are second- or third-generation repeat families.' where entry_id = 'paul-kollmann-monuments';
update public.places set links = '[{"kind": "website", "url": "https://promotionalresourcesinc.net/"}, {"kind": "facebook", "url": "https://www.facebook.com/PromotionalResources"}]'::jsonb, about = 'Promotional Resources sells branded apparel, promotional products and merchandise, with more than 25 years in the promotional products industry. It does its embroidery and screen printing in-house, which shortens delivery times, and works with over 3,000 suppliers. Its work includes safety, corporate, recognition, fulfillment and fundraising programs, custom logos, identity products and orders for athletic teams.' where entry_id = 'promotional-resources';
update public.places set links = '[{"kind": "website", "url": "http://quilldisc.com/"}]'::jsonb, about = 'Quill & Disc helps individuals and businesses patent, develop, and license or sell their inventions. Al and Julie Watkins founded the St. Joseph firm in 1996; Al is a registered patent agent who began his career as a patent examiner at the U.S. Patent and Trademark Office. Its clients range from garage inventors to multinational corporations, and some of their inventions have been licensed to some of the world''s largest companies.' where entry_id = 'quill-disc';
update public.places set links = '[{"kind": "website", "url": "https://rlcstjoe.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/RLCStJoe"}, {"kind": "instagram", "url": "https://www.instagram.com/rlcstjoemn"}]'::jsonb, about = 'Resurrection Lutheran Church is an ELCA congregation in the Southwestern Minnesota Synod that has worshipped together in St. Joseph since 1983. Its mission is to welcome joyfully, grow faithfully and serve gratefully in Jesus'' name. The church offers education for all ages, invites members into many ways of serving, and is a Fare For All site.' where entry_id = 'resurrection-lutheran-church';
update public.places set links = '[{"kind": "website", "url": "https://www.rtammphotography.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/people/R-Tamm-Photography/100068969207988/"}]'::jsonb, about = 'R. Tamm Photography is the St. Joseph studio of Roger Tamm, who began his career in photography in 1983. The studio takes family and children''s portraits, high school senior photos, corporate and business portraits, and school, sports and dance team pictures across central Minnesota. Schools and teams know it for a fun-loving, personal approach and careful work with large groups.' where entry_id = 'roger-tamm-photography';
update public.places set links = '[{"kind": "website", "url": "https://rothsteinchristmastreefarm.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/1634409233439792"}]'::jsonb, about = 'Rothstein Christmas Tree Farm is a family-owned Christmas tree farm on 156th Avenue in the countryside around St. Joseph. Families can walk the rows to find and cut their own tree, or choose from a wide variety of pre-cut trees. The farm sums up its work in its own motto: "Bringing Christmas Joy Home."' where entry_id = 'rothstein-christmas-tree-farm';
update public.places set links = '[{"kind": "website", "url": "https://saintjohnsabbey.org/"}, {"kind": "facebook", "url": "https://www.facebook.com/saintjohnsabbey"}, {"kind": "instagram", "url": "https://www.instagram.com/saintjohnsabbey"}]'::jsonb, about = 'Saint John''s Abbey is a Benedictine monastery in Collegeville, founded in 1856 when five monks came from St. Vincent Abbey in Pennsylvania to serve German Catholic immigrants in central Minnesota. Its Abbey Church, designed by Marcel Breuer, was completed in 1961. The monks pastor, teach, publish through Liturgical Press and grow food for their own table, and they run Abbey Woodworking and Abbey Organ Builders.' where entry_id = 'saint-johns-abbey';
update public.places set links = '[{"kind": "website", "url": "https://www.sixtwelveboutique.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/six.twelveboutiquemn"}, {"kind": "instagram", "url": "https://www.instagram.com/six.twelveboutique"}]'::jsonb where entry_id = 'six-twelve-boutique';
update public.places set links = '[{"kind": "website", "url": "https://dacotahpaper.com/distribution-area/"}, {"kind": "facebook", "url": "https://www.facebook.com/DacotahPaperCo"}]'::jsonb, about = 'Spectrum Supply, at 700 15th Avenue NE in St. Joseph, is the St. Cloud metro area branch of Dacotah Paper Co. Dacotah, a fourth-generation, family-owned wholesale distributor based in Fargo, bought Spectrum Supply in 2015. It carries more than 8,000 products, specializing in packaging, janitorial supplies and equipment, office supplies, food service supplies, and first aid and safety apparel.' where entry_id = 'spectrum-supply';
update public.places set links = '[{"kind": "website", "url": "https://sbm.osb.org/ministry/art-heritage-place/"}]'::jsonb, about = 'Saint Benedict''s Art & Heritage Place, built in 2000 at Saint Benedict''s Monastery, houses the Haehn Museum and the Whitby Gift Shop. The museum keeps nearly 9,000 artifacts, some from 1857, that tell the story of the Sisters of the Order of Saint Benedict, and welcomes school groups, classes and visitors for tours. The gift shop sells items often handmade by the sisters, from candles and tea towels to pottery and artwork.' where entry_id = 'st-benedicts-art-heritage';
update public.places set links = '[{"kind": "website", "url": "https://www.isd742.org/"}, {"kind": "facebook", "url": "https://www.facebook.com/isd742.org/"}, {"kind": "instagram", "url": "https://www.instagram.com/schooldistrict742/"}]'::jsonb where entry_id = 'st-cloud-area-school-district-742';
update public.places set links = '[{"kind": "website", "url": "https://www.stjoeministorage.com/"}]'::jsonb, about = 'St. Joe Mini Storage rents self-storage units at two sites in St. Joseph, one at 8480 County Road 75 and one at 719 19th Avenue NE. Units come in nine sizes, from 5 by 10 feet up to 10 by 50 feet, on month-to-month leases, and staff help renters pick the right size. Tenants manage their rentals through Deutz Properties'' online portal.' where entry_id = 'st-joe-mini-storage';
update public.places set links = '[{"kind": "website", "url": "https://www.benedictinecatholiccommunities.org/saint-john-the-baptist"}, {"kind": "facebook", "url": "https://www.facebook.com/sjtbparish"}]'::jsonb, about = 'St. John the Baptist is a Catholic parish on Fruit Farm Road near Collegeville that calls itself a progressive Catholic Benedictine community encountering Christ through Word and Sacrament. Masses are held in the Parish Center, and in summer the Sunday Mass moves outdoors when weather allows. Sunday Masses are recorded and posted to YouTube, and the parish shares its Benedictine Catholic Communities website with the Church of Saint Joseph.' where entry_id = 'st-john-baptist-parish';
update public.places set links = '[{"kind": "website", "url": "https://www.stjosephmn.gov/Facilities/Facility/Details/7"}]'::jsonb, about = 'A historical marker put up in the early 1940s in St. Joseph''s Monument Park recalls a blockhouse built in 1862, during the U.S.-Dakota War, when frightened settlers raised shelters for refuge. Three five-sided blockhouses of green timber from Joseph Linneman''s flour mill went up in different spots around town, with walls a foot thick and sides 50 feet long. The small park has benches, the memorial monument and parking.' where entry_id = 'st-joseph-blockhouse';
update public.places set links = '[{"kind": "website", "url": "https://st-joseph-community-food-shelf.square.site/"}, {"kind": "facebook", "url": "https://www.facebook.com/st.joefoodshelf"}]'::jsonb where entry_id = 'st-joseph-community-food-shelf';
update public.places set links = '[{"kind": "website", "url": "https://www.stjosephmn.gov/"}, {"kind": "facebook", "url": "https://www.facebook.com/CityofStJosephMN/"}]'::jsonb, about = 'The St. Joseph Government Center on Callaway Street East is home to the city''s government, including city administration and the police department. The City Council, a mayor and four councilmembers, meets there on the first and third Monday of the month to pass ordinances, set city policy and manage the budget.' where entry_id = 'st-joseph-government-center';
update public.places set links = '[]'::jsonb where entry_id = 'st-joseph-plumbing-heating-irrigation';
update public.places set links = '[{"kind": "website", "url": "https://stjosephtownship.org/"}]'::jsonb, about = 'St. Joseph Township is a township in Stearns County covering about 30 square miles, home to 1,924 people at the 2010 census. The township holds one public meeting a month, on the last Monday, at the Township Hall at 935 College Avenue South. Its website offers permit forms and details on reserving the township park shelter, and the township signed a ten-year fire contract with the City of St. Joseph in May 2024.' where entry_id = 'st-joseph-township-hall';
update public.places set links = '[{"kind": "website", "url": "https://lakewobegontrail.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/lakewobegontrails/"}]'::jsonb, about = 'The St. Joseph trailhead sits just under the water tower on the Lake Wobegon Trail, which runs 65 miles, 10 feet wide and paved end to end, from Waite Park west to Osakis. The trail passes through towns such as Collegeville, Avon, Albany, Melrose and Sauk Centre, and is open to walkers, bikers, rollerbladers and snowmobilers. Stearns County Parks maintains the trail, and the Lake Wobegon Trail Association promotes it.' where entry_id = 'st-joseph-trailhead-of-lake-wobegon-trai';
update public.places set links = '[{"kind": "website", "url": "http://www.dnr.state.mn.us/snas/detail.html?id=sna02038"}, {"kind": "instagram", "url": "https://www.instagram.com/minnesotadnr"}]'::jsonb, about = 'St. Wendel Tamarack Bog is a 650-acre Scientific and Natural Area run by the Minnesota DNR, set among farm fields and established in 2007. Despite its name it is mostly tamarack swamp, with a 10-acre calcareous fen, a globally rare plant community fed by mineral-rich groundwater. There are no trails, so visitors should expect wet, rough ground; winter is easiest, and fall turns the tamaracks gold.' where entry_id = 'st-wendel-tamarack-bog-scientific-natura';
update public.places set links = '[{"kind": "website", "url": "https://www.sunset-eq.com/"}]'::jsonb, about = 'Sunset Equipment and Supply has made and sold bulk milk cooling systems and replacement parts for the dairy industry since 1953, shipping through dealers and distributors across the country and abroad. Under the Sunset Companies name, Sunset Manufacturing works from 417 First Avenue NE in St. Joseph, fabricating sheet metal parts and assemblies such as machine guards, conveyors, walkways and small weldments, with added machining, for customers across the Upper Midwest.' where entry_id = 'sunset-manufacturing-sunset-equipment';
update public.places set links = '[{"kind": "facebook", "url": "https://www.facebook.com/283115511817520"}]'::jsonb where entry_id = 't-r-glass-woodworks';
update public.places set links = '[{"kind": "website", "url": "https://tamarackmaterials.com/"}]'::jsonb, about = 'Tamarack Materials supplies construction materials and building supplies, including drywall, steel framing, insulation, acoustical ceilings and building envelope products, to contractors in Minnesota, the Dakotas, Iowa and Wisconsin. Its St. Joseph yard on County Road 133 keeps one of the largest in-stock inventories of steel framing in Central Minnesota, ready for pickup or delivery to commercial and residential jobsites.' where entry_id = 'tamarack-materials';
update public.places set links = '[{"kind": "website", "url": "https://www.tccmaterials.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/TCCMaterialsHardscapePrecast"}, {"kind": "instagram", "url": "https://www.instagram.com/tccmaterials_hardscapesprecast"}]'::jsonb, about = 'TCC Materials makes Borgert concrete paving stones, slabs and wall products at its plant on Ridgewood Road in St. Joseph, the longtime home of Borgert Products. Lawrence A. Borgert started that business in 1923 in East St. Cloud, and his son Kenneth moved it to St. Joseph in 1953; it stayed in the family before joining TCC Materials. TCC began in 1927 as Twin City Concrete Products Company and now makes packaged concrete, masonry and hardscape materials across North America.' where entry_id = 'tcc-materials';
update public.places set links = '[{"kind": "website", "url": "http://www.floorguy.net/"}, {"kind": "facebook", "url": "https://www.facebook.com/TMT-Integrity-Flooring-LLC-153759377299"}]'::jsonb, about = 'TMT Integrity Flooring is a family wood-flooring business led by craftsman Todd Theisen. It installs, sands, finishes and refurbishes hardwood floors, and is known for inlay designs and for extending and feathering new boards to match existing flooring. The business favors green, breathable finishes over urethane varnishes, an approach tied to the family''s Creekwood Acres farm.' where entry_id = 'tmt-integrity-flooring';
update public.places set links = '[{"kind": "website", "url": "https://trautcompanies.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/trautcompanies"}]'::jsonb, about = 'Traut Companies is a water well and water treatment company based on County Road 133 in St. Joseph. Cousins Mark and Dave Traut, who grew up in the family well-drilling business started in 1959, opened Mark J. Traut Wells in 1982 with 10 employees; it now has more than 80 full-time staff. It drills wells, services pumps, installs geothermal heating and cooling, irrigation and water treatment, and runs a certified water lab for homes, farms and towns.' where entry_id = 'traut-companies';
update public.places set links = '[{"kind": "website", "url": "https://truckaccessoriesdirect.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/profile.php?id=100089818405338"}, {"kind": "instagram", "url": "https://www.instagram.com/truckaccessoriesdirect"}]'::jsonb, about = 'Truck Accessories Direct sells and installs aftermarket parts for pickup trucks and SUVs from its shop on 15th Avenue in St. Joseph. Its range covers bumpers and grille guards, running boards, tonneau covers, fender flares, lift and leveling kits, lighting, floor mats and seat covers, along with hitches, fifth-wheel and gooseneck setups for towing. The staff use the products they sell and install the brands they recommend.' where entry_id = 'truck-accessories-direct';
update public.places set links = '[]'::jsonb, about = 'The Army Reserve center in St. Joseph is home to the 367th Engineer Battalion, part of the 416th Theater Engineer Command. An armory was first planned for the city in 1989, and ground was broken on the $11.8 million center in April 2013, with about 40,000 square feet for offices, a learning center, library, assembly hall, weapons simulator and fitness area. In 2016 the battalion won the Walter T. Kerwin Jr. Readiness Award for top Guard and Reserve battalions.' where entry_id = 'us-army-reserve-training';
update public.places set links = '[{"kind": "website", "url": "https://thewholeyouwellnesscollective.com/"}, {"kind": "facebook", "url": "https://www.facebook.com/thewholeyouwellnesscollective"}, {"kind": "instagram", "url": "https://www.instagram.com/thewholeyouwellnesscollective"}]'::jsonb, about = 'The Whole You Wellness Collective is a holistic wellness practice in St. Joseph run by registered nurse Trisha Kubasek. She is an Advanced Certified Quantum Neuro Reset Therapy (QNRT) practitioner and a certified group fitness instructor, and pairs QNRT sessions with nutrition guidance and body movement coaching. The practice grew out of her own change in health that began in 2016.' where entry_id = 'whole-you-wellness-collective';
